async function api(path,method='GET',body){const r=await fetch('/api/'+path,{method,headers:method==='GET'?{}:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Object.assign(new Error(d.error||'Não foi possível concluir.'),{status:r.status});return d;}
function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),4000)}
async function refresh(){items=await api('items');render()}
function filtered(){return selectItems(items,{category,status,query,sort,media,transcript,engagement,minLikes,minComments})}
function render(){if(!currentUser)return renderLogin();const base=items.filter(i=>category==='all'||i.category===category);const count=s=>base.filter(i=>s==='all'||i.status===s).length;const name=category==='all'?'Todos os conteúdos':categories[category].name;
 app.innerHTML=`<aside class="sidebar"><div class="brand"><div class="brand-mark">T</div><div><strong>TASSITANI</strong><small>CENTRAL DE CONTEÚDOS</small></div></div><button class="nav-btn ${!pageMode&&!teamMode&&category==='all'&&status==='all'?'active':''}" data-nav="all">${icon('grid')}Todos os conteúdos<span class="nav-count">${items.length}</span></button><div class="nav-label">COLEÇÕES</div>${Object.entries(categories).map(([k,c])=>`<button class="nav-btn ${!pageMode&&!teamMode&&category===k?'active':''}" data-nav="${k}"><span class="category-dot" style="--cat:${c.color}"></span>${c.name}<span class="nav-count">${items.filter(i=>i.category===k).length}</span></button>`).join('')}<div class="nav-label">PRODUÇÃO</div><button class="nav-btn" data-production="pending">${icon('circle')}Não feitos<span class="nav-count">${items.filter(i=>i.status==='pending').length}</span></button><button class="nav-btn" data-production="done">${icon('check')}Feitos<span class="nav-count">${items.filter(i=>i.status==='done').length}</span></button><div class="nav-label">MEU INSTAGRAM</div><button class="nav-btn ${teamMode==='instagram'?'active':''}" data-team="instagram">${icon('globe')}Instagram & Analytics</button><div class="nav-label">EQUIPE</div><button class="nav-btn ${teamMode==='tasks'?'active':''}" data-team="tasks">${icon('check')}Tarefas</button><button class="nav-btn ${teamMode==='folders'?'active':''}" data-team="folders">${icon('link')}Central de Pastas</button>${pageOwner()?`<div class="nav-label">MEU REPERTÓRIO</div><button id="page-references" class="nav-btn ${pageMode?'active':''}">${icon('globe')}Página de Referência</button>`:''}<div class="sidebar-bottom"><button class="nav-btn" id="transcription-setup">${icon('list')}Conectar transcrição</button><button class="nav-btn" id="export">${icon('download')}Exportar acervo</button><div class="profile"><div class="avatar">${esc(currentUser.name.split(/\s+/).map(n=>n[0]).slice(0,2).join(''))}</div><div><strong>${esc(currentUser.name)}</strong><small>Minha conta</small></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb"><button class="mobile-menu" aria-label="Abrir menu">${icon('menu')}</button><span>Conteúdos</span><span>/</span><b>Central de conteúdos</b></div><div class="top-actions"><span class="public-badge">${icon('globe')}Acesso da equipe</span><button class="text-btn" id="auth">${icon(editor?'logout':'edit')}${editor?'Sair':'Entrar'}</button></div></header><section class="workspace"><div class="eyebrow">BRUNNO TASSITANI</div><div class="heading"><div><h1>${name}</h1><p class="subtitle">Referências, ideias e produção em um só lugar.</p></div><div class="actions"><button class="btn" id="batch">${icon('link')}Importar links</button><button class="btn primary" id="new">${icon('plus')}Novo conteúdo</button></div></div><div class="stats">${[['Referências salvas',count('all'),'Seu acervo de inspirações','grid'],['Não feitos',count('pending'),'Ideias esperando sair do papel','circle'],['Em produção',count('producing'),'Conteúdos em desenvolvimento','clock'],['Feitos',count('done'),'Mais uma ideia ganhou vida','check']].map(([label,note,desc,ic])=>`<div class="stat"><div class="stat-label">${label}${icon(ic)}</div><strong>${note.toString().padStart(2,'0')}</strong><small>${desc}</small></div>`).join('')}</div><div class="toolbar"><div class="tabs">${[['all','Todos'],['pending','Não feitos'],['producing','Em produção'],['done','Feitos']].map(([k,label])=>`<button class="tab ${status===k?'active':''}" data-status="${k}">${label}<span>${count(k)}</span></button>`).join('')}</div></div><div class="controls"><label class="search">${icon('search')}<input id="search" aria-label="Buscar conteúdos" placeholder="Buscar título, ideia ou @..." value="${esc(query)}"></label><select id="sort" aria-label="Ordenar conteúdos"><option value="new">Mais recentes primeiro</option><option value="old">Mais antigos primeiro</option><option value="title">Título: A–Z</option><option value="likes">Mais curtidas</option><option value="comments">Mais comentários</option></select><div class="view-switch"><button data-view="grid" class="${view==='grid'?'active':''}" aria-label="Visualizar em cards">${icon('grid')}</button><button data-view="list" class="${view==='list'?'active':''}" aria-label="Visualizar em lista">${icon('list')}</button></div></div><details class="filter-disclosure"><summary>Filtros</summary><div class="filter-row"><label>Formato<select id="media-filter"><option value="all">Todos os formatos</option><option value="carousel">Carrossel com slides</option><option value="reel">Reels / vídeo</option><option value="image">Imagem única</option><option value="reference">Outras referências</option><option value="idea">Ideia sem link</option></select></label><label>Transcrição<select id="transcript-filter"><option value="all">Todas</option><option value="done">Com transcrição</option><option value="missing">Sem transcrição</option></select></label><label>Métricas<select id="engagement-filter"><option value="all">Todas</option><option value="available">Com dados públicos</option><option value="missing">Sem dados públicos</option></select></label><label>Mín. curtidas<input id="min-likes" type="number" min="0" step="1" placeholder="Qualquer" value="${esc(minLikes)}"></label><label>Mín. comentários<input id="min-comments" type="number" min="0" step="1" placeholder="Qualquer" value="${esc(minComments)}"></label><button class="text-btn" id="clear-filters">Limpar filtros</button></div></details><p class="result-info" id="result-info"></p><div id="cards" class="grid ${view==='list'?'list':''}"></div><div id="pagination" class="pagination"></div></section></main>`;
 renderCards();document.querySelector('#sort').value=sort;
 for(const [id,value,change] of [['media-filter',media,v=>media=v],['transcript-filter',transcript,v=>transcript=v],['engagement-filter',engagement,v=>engagement=v]]){const el=document.getElementById(id);el.value=value;el.onchange=()=>{change(el.value);page=1;renderCards()};}
 document.getElementById('min-likes').oninput=e=>{minLikes=e.target.value;page=1;renderCards()};document.getElementById('min-comments').oninput=e=>{minComments=e.target.value;page=1;renderCards()};document.getElementById('clear-filters').onclick=()=>{media=transcript=engagement='all';minLikes=minComments=query='';status='all';page=1;render()};

 document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{teamMode='';pageMode=false;category=b.dataset.nav;status='all';query='';page=1;render();window.scrollTo({top:0})});document.querySelectorAll('[data-production]').forEach(b=>b.onclick=()=>{teamMode='';pageMode=false;category='all';status=b.dataset.production;page=1;render();window.scrollTo({top:0})});document.querySelectorAll('[data-status]').forEach(b=>b.onclick=()=>{status=b.dataset.status;page=1;render()});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});document.querySelector('#search').oninput=e=>{query=e.target.value;page=1;renderCards()};document.querySelector('#sort').onchange=e=>{sort=e.target.value;page=1;renderCards()};document.querySelector('#auth').onclick=async()=>{if(editor){try{await api('logout','POST',{});editor=false;currentUser=null;items=[];window.google?.accounts.id.disableAutoSelect();renderLogin()}catch(e){toast(e.message)}}else login()};document.querySelector('#new').onclick=()=>editor?edit():login(()=>edit());document.querySelector('#batch').onclick=()=>editor?batch():login(()=>batch());document.querySelector('.mobile-menu').onclick=()=>document.querySelector('.sidebar').classList.toggle('open');document.querySelector('#export').onclick=exportItems;document.querySelector('#transcription-setup').onclick=connectionGuide;
 const pagesButton=document.querySelector('#page-references');if(pagesButton)pagesButton.onclick=()=>{teamMode='';pageMode=true;render();window.scrollTo({top:0});};if(pageMode&&pageOwner())renderPageReferences();document.querySelectorAll('[data-team]').forEach(b=>b.onclick=()=>{teamMode=b.dataset.team;pageMode=false;render();window.scrollTo({top:0});});if(teamMode==='instagram')mountInstagram(document.querySelector('.workspace'),{api,toast});else if(teamMode)renderTeam();
}
function preview(i,detail=false){const slides=slideList(i);if(slides.length){return `<div class="slide-viewer" data-viewer="${i.id}"><div class="slide-stage"><img src="${esc(slides[0].url)}" alt="Slide 1 de ${slides.length}: ${esc(i.title)}" loading="lazy"></div>${slides.length>1?`<div class="slide-controls"><button type="button" data-step="-1" aria-label="Slide anterior" disabled>←</button><span aria-live="polite">1 / ${slides.length}</span><button type="button" data-step="1" aria-label="Próximo slide">→</button></div><div class="slide-thumbnails">${slides.map((s,n)=>`<button type="button" data-slide="${n}" aria-label="Ver slide ${n+1}" aria-pressed="${n===0}"><img src="${esc(s.url)}" alt="" loading="lazy"></button>`).join('')}</div>`:''}</div>`;}
 if(i.category==='carrosseis'&&mediaKind(i)!=='reel'&&i.thumbnail)return `<div class="slide-stage"><img src="${esc(i.thumbnail)}" alt="Capa disponível: ${esc(i.title)}" loading="lazy"></div><p class="embed-note">Capa salva. A sequência completa desta referência não está disponível.</p>`;
 if(i.thumbnail)return `<div class="reel-cover"><img src="${esc(i.thumbnail)}" alt="Capa: ${esc(i.title)}" loading="lazy"></div>`;
 if(i.url)return `<div class="missing-cover">${icon('grid')}<strong>Capa não disponível</strong><p>${esc(i.title)}</p><a href="${esc(i.url)}" target="_blank" rel="noopener noreferrer">Ver publicação no Instagram ↗</a></div>`;
 return `<div class="fallback">${icon('edit')}Ideia sem referência visual</div>`;}
function bindMedia(scope){scope.querySelectorAll('[data-viewer]').forEach(el=>{const i=items.find(x=>x.id===Number(el.dataset.viewer)),slides=slideList(i);let current=0;const set=n=>{current=Math.max(0,Math.min(slides.length-1,n));const image=el.querySelector('.slide-stage img');image.src=slides[current].url;image.alt=`Slide ${current+1} de ${slides.length}: ${i.title}`;el.querySelector('[aria-live]').textContent=`${current+1} / ${slides.length}`;el.querySelector('[data-step="-1"]').disabled=current===0;el.querySelector('[data-step="1"]').disabled=current===slides.length-1;el.querySelectorAll('[data-slide]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.slide)===current));};el.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>set(current+Number(b.dataset.step)));el.querySelectorAll('[data-slide]').forEach(b=>b.onclick=()=>set(Number(b.dataset.slide)));});}

function metricsPanel(i){const fmt=v=>v==null?'—':new Intl.NumberFormat('pt-BR').format(v);return `<div class="engagement"><span title="Curtidas públicas">♡ <b>${fmt(i.likes)}</b><small>curtidas</small></span><span title="Comentários públicos">◯ <b>${fmt(i.comments)}</b><small>comentários</small></span><span title="O Instagram não forneceu uma contagem pública de compartilhamentos">↗ <b>${fmt(i.shares)}</b><small>compartilhamentos</small></span></div><div class="metrics-caption"><span>${i.metrics_checked_at?`${i.metrics_approximate?'Valores aproximados · ':''}Consulta em ${new Date(i.metrics_checked_at).toLocaleDateString('pt-BR')}${i.metrics_state==='unavailable'?' · números não disponibilizados':''}`:'Métricas ainda não consultadas'} · — = indisponível</span>${editor&&i.url?`<button type="button" data-metrics="${i.id}">Consultar</button>`:''}</div>`;}
function bindMetrics(scope){scope.querySelectorAll('[data-metrics]').forEach(b=>b.onclick=async()=>{b.disabled=true;b.textContent='Consultando…';try{const result=await api('items/'+b.dataset.metrics+'/metrics','POST',{});await refresh();toast(result.metrics.state==='available'?'Métricas públicas atualizadas.':'O Instagram não liberou os números desta publicação.')}catch(e){toast(e.message);b.disabled=false;b.textContent='Consultar'}});}
function renderCards(){const full=filtered();const pages=Math.max(1,Math.ceil(full.length/pageSize));page=Math.min(page,pages);const list=full.slice((page-1)*pageSize,page*pageSize);document.querySelector('#pagination').innerHTML=pages>1?`<button class="btn" id="prev-page" ${page===1?'disabled':''}>← Anterior</button><span>Página ${page} de ${pages}</span><button class="btn" id="next-page" ${page===pages?'disabled':''}>Próxima →</button>`:'';for(const [id,step] of [['prev-page',-1],['next-page',1]]){const b=document.getElementById(id);if(b)b.onclick=()=>{page+=step;renderCards();document.querySelector('.controls').scrollIntoView({block:'start',behavior:'smooth'})};}document.querySelector('#result-info').textContent=`${full.length} ${full.length===1?'conteúdo':'conteúdos'}${query?' encontrados':''}`;document.querySelector('#cards').innerHTML=list.length?list.map(i=>`<article class="card"><div class="card-label"><span class="cover-tag"><span class="category-dot" style="--cat:${categories[i.category].color}"></span>${categories[i.category].name}</span>${i.url?`<a class="post-link" href="${esc(i.url)}" target="_blank" rel="noopener noreferrer" aria-label="Abrir publicação original">${icon('arrow')}</a>`:''}</div><div class="cover">${preview(i)}</div><div class="visible-engagement">${metricsPanel(i).split('<div class="metrics-caption">')[0]}</div><div class="card-body"><button class="card-title" data-edit="${i.id}"><h2>${esc(i.title)}</h2></button><div class="reference-meta">${i.creator_handle?`<a href="https://www.instagram.com/${esc(i.creator_handle)}/" target="_blank" rel="noopener noreferrer">@${esc(i.creator_handle)}</a>`:'<span class="creator-pending">—</span>'}<time datetime="${esc(i.created_at)}" title="Data de inclusão">${new Date(i.created_at).toLocaleDateString('pt-BR')}</time></div><div class="inline-notes" data-notes-area="${i.id}">${notesButton(i)}</div><details class="card-details"><summary>Detalhes da referência</summary><div class="card-details-content"><p class="content-author">Adicionado por <strong>${esc(teamConfig.members?.find(m=>m.email===i.created_by)?.name||i.created_by||'Equipe')}</strong></p><div class="metrics-area">${metricsPanel(i).slice(metricsPanel(i).indexOf('<div class="metrics-caption">'))}</div>${templateSection(i)}${transcriptButton(i)}</div></details><div class="card-footer"><span class="status ${i.status}">${icon(i.status==='done'?'check':i.status==='producing'?'clock':'circle')}${i.status==='done'?'Feito':i.status==='producing'?'Em produção':'Não feito'}</span><button class="small-btn" data-edit="${i.id}">${icon('edit')}${editor?'Ideias':'Ver ideias'}</button><button class="small-btn" data-done="${i.id}" aria-label="${i.status==='done'?'Desmarcar feito':'Marcar como feito'}: ${esc(i.title)}">${icon(i.status==='done'?'circle':'check')}</button></div></div></article>`).join(''):`<div class="empty">${icon('grid')}<h2>${query?'Nenhum conteúdo encontrado':'Espaço para a próxima ideia'}</h2><p>${query?'Tente outro termo ou altere os filtros.':'Cole suas referências e comece a construir esta coleção.'}</p><button class="btn primary" id="empty-add">${icon('plus')}Adicionar conteúdo</button></div>`;
 document.querySelectorAll('[data-notes]').forEach(b=>b.onclick=()=>openInlineNotes(Number(b.dataset.notes)));
 bindMedia(document.querySelector('#cards'));bindMetrics(document.querySelector('#cards'));bindTemplateCopy(document.querySelector('#cards'));bindTranscripts(document.querySelector('#cards'));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(items.find(i=>i.id===+b.dataset.edit)));document.querySelectorAll('[data-done]').forEach(b=>b.onclick=()=>{const i=items.find(i=>i.id===+b.dataset.done);const save=async()=>{try{await api('items/'+i.id,'PUT',{...i,status:i.status==='done'?'pending':'done'});await refresh();toast(i.status==='done'?'Conteúdo voltou para não feitos.':'Conteúdo marcado como feito.')}catch(e){toast(e.message)}};editor?save():login(save)});const empty=document.querySelector('#empty-add');if(empty)empty.onclick=()=>editor?edit():login(()=>edit());}
function notesButton(i){return `<button type="button" class="card-notes notes-trigger" data-notes="${i.id}" aria-label="${i.notes?'Editar':'Adicionar'} ideia: ${esc(i.title)}"><span>${esc(i.notes||'Adicionar ideia')}</span><small>${icon('edit')}${i.notes?'Editar':'Escrever'}</small></button>`;}
function openInlineNotes(id){
 if(!editor)return login(()=>openInlineNotes(id));
 const item=items.find(i=>i.id===id),area=document.querySelector(`[data-notes-area="${id}"]`);
 if(!item||!area)return;
 const version=item.version;
 area.innerHTML=`<form class="notes-form"><label for="notes-${id}">Minha ideia</label><textarea id="notes-${id}" maxlength="30000" rows="5" placeholder="Escreva seu gancho, roteiro ou adaptação…">${esc(item.notes)}</textarea><p class="notes-error" role="alert"></p><div class="notes-actions"><button type="button" class="btn" data-cancel-notes>Cancelar</button><button type="submit" class="btn primary">Salvar ideia</button></div></form>`;
 const form=area.querySelector('form'),input=form.querySelector('textarea'),save=form.querySelector('[type=submit]'),cancel=form.querySelector('[data-cancel-notes]');
 const close=()=>{area.innerHTML=notesButton(items.find(i=>i.id===id)||item);const button=area.querySelector('[data-notes]');button.onclick=()=>openInlineNotes(id);button.focus({preventScroll:true});};
 cancel.onclick=close;
 form.onsubmit=async e=>{e.preventDefault();if(save.disabled)return;const notes=input.value;save.disabled=cancel.disabled=input.disabled=true;save.textContent='Salvando…';form.querySelector('[role=alert]').textContent='';try{await api('items/'+id,'PUT',{notes,version});Object.assign(item,{notes,version:version+1});close();toast('Ideia salva.');}catch(error){form.querySelector('[role=alert]').textContent=error.message;}finally{save.disabled=cancel.disabled=input.disabled=false;save.textContent='Salvar ideia';}};
 input.onkeydown=e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();form.requestSubmit();}};
 input.focus({preventScroll:true});input.setSelectionRange(input.value.length,input.value.length);
}
function transcriptButton(i){if(i.category==='carrosseis'&&mediaKind(i)!=='reel'&&!i.transcription_state)return '';const labels={done:'Ver transcrição',processing:'Transcrevendo…',failed:'Transcrição não concluída'};return `<button type="button" class="transcript-button ${i.transcription_state==='done'?'saved':''}" data-transcript="${i.id}">${icon(i.transcription_state==='done'?'check':'list')}${labels[i.transcription_state]||'Transcrever'}</button>`;}
function bindTranscripts(scope){scope.querySelectorAll('[data-transcript]').forEach(b=>b.onclick=()=>openTranscript(Number(b.dataset.transcript)));}
async function connectionGuide(){if(!editor)return login(connectionGuide);try{const cfg=await api('transcription-config');const f=show('Conectar transcrição',cfg.configured?'Chave configurada no servidor. A validação ocorre ao transcrever.':'Configure uma vez para transcrever pela central.',`<div class="help-note">A central e as transcrições ficam no seu servidor. A OpenAI recebe o áudio para transcrever e organiza o texto em blocos.</div><ol class="connection-steps"><li>Entre na <a href="https://platform.openai.com" target="_blank" rel="noopener noreferrer">plataforma da OpenAI</a> e configure a cobrança da API.</li><li>Crie uma chave em <a href="https://platform.openai.com/api-keys" target="_blank" rel="noopener noreferrer">API Keys</a>.</li><li>Na instalação da central, configure <code>OPENAI_API_KEY</code> no arquivo <code>.env</code> ou nas variáveis do aplicativo na Hostinger. A chave fica somente no servidor.</li><li>Reinicie o aplicativo. Com Docker Compose, execute <code>docker compose up -d --build</code>. Na instalação Node.js direta, use <code>npm start</code>.</li><li>Abra um vídeo e clique em Transcrever. A central tenta buscar o vídeo público automaticamente. Se o Instagram não liberar o arquivo, use o envio manual.</li></ol><p class="source">Formato aceito: MP3, MP4, M4A, WAV, WebM, OGG, FLAC, MPEG ou MPGA; até 24 MB. Para vídeos longos, prefira trechos curtos. O modelo é GPT-4o Mini Transcribe. A conta da API é cobrada por uso.</p>`,`<button type="button" class="btn" data-close>Fechar</button>`);f.onsubmit=e=>e.preventDefault();}catch(e){toast(e.message)}}
const transcriptLabels={gancho:'Gancho',contexto:'Contexto',desenvolvimento:'Desenvolvimento',cta:'CTA · chamada para ação'};
function transcriptBlocks(t){let data;try{data=JSON.parse(t.structure||'null')}catch{}return Array.isArray(data?.segments)?data.segments.filter(s=>transcriptLabels[s.label]&&typeof s.text==='string'):[];}
function transcriptCopy(t,structured=true){const blocks=transcriptBlocks(t);return structured&&blocks.length?blocks.map(s=>transcriptLabels[s.label].toUpperCase()+'\n'+s.text).join('\n\n'):t.text;}
async function startVideoTranscription(id,analysis=false){try{await api('items/'+id+'/transcription'+(analysis?'/analysis':''),'POST',analysis?{}:{source:'instagram'});await openTranscript(id,false);}catch(e){toast(e.message);await openTranscript(id,false);}}
async function openTranscript(id,autoStart=true){try{
 const i=items.find(x=>x.id===id);if(!i)return;
 const {transcript:t}=await api('items/'+id+'/transcription');
 if(t?.state==='processing'){
  const phases=['fetching','transcribing','organizing'],labels=['Buscando o vídeo','Transcrevendo a fala','Organizando os blocos'];
  const phase=Math.max(0,phases.indexOf(t.phase));
  const f=show('Preparando sua transcrição',i.title,`<div class="transcription-steps">${labels.map((label,n)=>`<div data-phase="${phases[n]}" class="${n<phase?'complete':n===phase?'current':''}"><span>${n+1}</span>${label}</div>`).join('')}</div><p class="source">Pode fechar esta janela. O resultado será salvo nesta referência.</p><p class="transcript-progress" role="status">${labels[phase]}…</p>`,`<button type="button" class="btn" data-close>Continuar navegando</button>`);
  let polling=false;const poll=setInterval(async()=>{if(!f.isConnected||!modal.open){clearInterval(poll);return;}if(polling)return;polling=true;try{const next=(await api('items/'+id+'/transcription')).transcript;if(next?.state!=='processing'){clearInterval(poll);await refresh();if(f.isConnected&&modal.open)openTranscript(id,false);else toast('Transcrição concluída.');return;}const index=Math.max(0,phases.indexOf(next.phase));f.querySelectorAll('[data-phase]').forEach((el,n)=>el.className=n<index?'complete':n===index?'current':'');f.querySelector('[role=status]').textContent=labels[index]+'…';}catch(e){clearInterval(poll);f.querySelector('[role=status]').textContent='A conexão foi interrompida. Reabra a transcrição para consultar o resultado.';}finally{polling=false;}},2500);return;
 }
 if(t?.text){
  const blocks=transcriptBlocks(t),hasCTA=blocks.some(s=>s.label==='cta');
  const f=show('Transcrição do vídeo',i.title,`<div class="transcript-meta"><span class="transcript-saved">${icon('check')}Salva nesta referência</span><span>${t.text.trim().split(/\s+/).length} palavras</span></div>${t.warning?`<p class="help-note">${esc(t.warning)}</p>`:''}${blocks.length?`<div class="transcript-sections">${blocks.map((s,n)=>`<section class="transcript-section ${s.label}"><div class="transcript-section-label"><span>${String(n+1).padStart(2,'0')}</span><h3>${transcriptLabels[s.label]}</h3></div><p>${esc(s.text)}</p></section>`).join('')}</div>${!hasCTA?'<p class="transcript-absence">Nenhuma chamada para ação explícita foi identificada.</p>':''}<p class="source">Divisão sugerida por IA. Os trechos mantêm as palavras transcritas.</p>`:`<div class="transcript-full">${esc(t.text)}</div><p class="source">${esc(t.analysis_error||t.error||'A transcrição está salva. Você pode organizar a leitura em blocos.')}</p><button class="btn" type="button" id="organize-transcript">Organizar em gancho, contexto e CTA</button>`}<details class="transcript-original"><summary>Texto integral e origem</summary><textarea readonly rows="9" aria-label="Transcrição integral">${esc(t.text)}</textarea><p class="source">${esc(t.filename)} · ${t.completed_at?new Date(t.completed_at).toLocaleString('pt-BR'):''}</p>${t.source_url?`<a class="text-btn" href="${esc(t.source_url)}" target="_blank" rel="noopener noreferrer">Abrir vídeo original ↗</a>`:''}<button class="text-btn" type="button" id="copy-original">Copiar texto integral</button></details>`,`<button type="button" class="btn" data-close>Fechar</button><button type="button" class="btn primary" id="copy-transcript">${blocks.length?'Copiar blocos':'Copiar transcrição'}</button>`);
  const copy=async structured=>{try{await navigator.clipboard.writeText(transcriptCopy(t,structured));toast('Texto copiado.');}catch{const area=f.querySelector('textarea');area.closest('details').open=true;area.select();toast('Texto selecionado para copiar.');}};
  f.querySelector('#copy-transcript').onclick=()=>copy(true);f.querySelector('#copy-original').onclick=()=>copy(false);const organize=f.querySelector('#organize-transcript');if(organize)organize.onclick=()=>{organize.disabled=true;startVideoTranscription(id,true);};f.onsubmit=e=>e.preventDefault();return;
 }
 const cfg=await api('transcription-config');
 if(autoStart&&!t&&cfg.configured&&i.url){await startVideoTranscription(id);return;}
 const f=show('Transcrever vídeo',i.title,`${t?.error?`<p class="help-note">${esc(t.error)}</p>`:''}${!cfg.configured?'<p class="help-note">Conecte a chave da OpenAI no servidor para começar.</p>':''}<p class="source">A central busca o vídeo público e salva a fala organizada nesta referência. O processamento usa o saldo da sua API.</p><button type="button" class="btn primary auto-transcribe" id="auto-transcribe" ${!cfg.configured||!i.url?'disabled':''}>${icon('play')}${t?'Tentar pelo Instagram novamente':'Transcrever pelo Instagram'}</button><details class="transcript-upload" ${t?.state==='failed'?'open':''}><summary>Enviar arquivo como alternativa</summary><label class="field">Vídeo ou áudio<input type="file" name="media" accept=".mp3,.mp4,.m4a,.wav,.webm,.ogg,.flac,.mpeg,.mpga" ${!cfg.configured?'disabled':''}><small>Até 24 MB. Use o arquivo correspondente a esta referência.</small></label><button type="submit" class="btn" ${!cfg.configured?'disabled':''}>Enviar e transcrever</button></details><p class="transcript-progress" role="status"></p>`,`<button type="button" class="btn" data-close>Fechar</button>`);
 f.querySelector('#auto-transcribe').onclick=()=>{f.querySelector('#auto-transcribe').disabled=true;startVideoTranscription(id);};
 f.onsubmit=async e=>{e.preventDefault();const file=f.elements.media.files[0];if(!file){error(Error('Escolha o arquivo correspondente ao vídeo.'));return;}if(file.size>cfg.max_bytes){error(Error('Envie um arquivo de até 24 MB.'));return;}const button=f.querySelector('[type=submit]');button.disabled=true;f.querySelector('[role=status]').textContent='Enviando arquivo…';try{const data=new FormData();data.append('file',file);const response=await fetch('/api/items/'+id+'/transcription',{method:'POST',body:data});const result=await response.json();if(!response.ok)throw Error(result.error||'Não foi possível enviar.');if(f.isConnected&&modal.open)await openTranscript(id,false);else toast('Arquivo enviado. A transcrição será salva.');}catch(e){if(f.isConnected)error(e);else toast(e.message);}finally{button.disabled=false;}};
 }catch(e){toast(e.message);}}

function templatePrompt(i){return `Use este briefing como referência para criar um carrossel original para Brunno Tassitani.

TEMPLATE: ${i.template_name||'A definir'}
TEMA: ${i.title}
REFERÊNCIA: ${i.url||'Não informada'}

DESCRIÇÃO VISUAL:
${i.visual_description||'Descrição ainda não preenchida. Analise as imagens que eu anexar antes de definir o estilo.'}

BASE DA DESCRIÇÃO: ${i.visual_basis||'Descrição cadastrada pelo editor.'}

MINHAS IDEIAS:
${i.notes||'Vou informar o conteúdo a seguir.'}

INSTRUÇÕES PARA A NOVA CRIAÇÃO:
Use a descrição como direção visual. O código do template é uma identificação interna: ele não permite acessar a referência sozinho. Se as imagens não estiverem acessíveis, peça que eu anexe a capa e os slides que quero usar de referência. Não invente a aparência de slides que não foram vistos.
Proponha uma sequência de capa, desenvolvimento e fechamento, deixando claro que a sequência é nova. Use português do Brasil e confira acentos e legibilidade. Mantenha cores, tipografia, margens e personagens consistentes. Sugestão de formato de saída: 1080 × 1350 px, sujeito à minha preferência. Não copie textos, logotipos ou identidades de terceiros; use minha identidade quando eu fornecer os elementos.
Primeiro apresente o roteiro por slide e os prompts visuais. Depois gere uma imagem por slide conforme eu solicitar.`;}
function templateGallery(i){let slides;try{slides=JSON.parse(i.template_slides||'[]')}catch{return ''}if(!Array.isArray(slides)||!slides.length)return '';return `<div class="template-gallery" aria-label="Slides da referência">${slides.filter(s=>/^\/uploads\/[a-f0-9]{32}\.(png|jpeg|webp)$/.test(s.url)).map((s,n)=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer" title="Abrir slide ${n+1}"><img src="${esc(s.url)}" alt="Slide ${n+1} da referência" loading="lazy"><span>${n+1}</span></a>`).join('')}</div><p class="source">Clique em um slide para ampliar. Use as imagens como referência junto do prompt.</p>`;}
function templateSection(i){if(i.category!=='carrosseis')return '';return `<div class="template-block"><span class="template-name">${esc(i.template_name||'Template a definir')}</span><details><summary>Descrição visual do template</summary><div class="template-content"><p class="template-basis">${esc(i.visual_basis||'Descrição cadastrada pelo editor.')}</p><p class="visual-description">${esc(i.visual_description||'Abra a edição para descrever cores, tipografia e composição desta referência.')}</p>${templateGallery(i)}<button type="button" class="btn" data-copy-template="${i.id}">${icon('list')}Copiar prompt para o GPT</button></div></details></div>`;}
function bindTemplateCopy(scope){scope.querySelectorAll('[data-copy-template]').forEach(b=>b.onclick=async()=>{const i=items.find(i=>i.id===Number(b.dataset.copyTemplate));if(!i)return;const text=templatePrompt(i);try{await navigator.clipboard.writeText(text);toast('Prompt copiado. Cole no GPT e anexe as imagens de referência.')}catch{const form=show('Prompt para o GPT','Selecione e copie o texto abaixo.',`<label class="field">Prompt<textarea readonly rows="14">${esc(text)}</textarea></label>`,`<button type="button" class="btn" data-close>Fechar</button>`);form.querySelector('textarea').select();}});}
function show(title,subtitle,html,actions){modal.innerHTML=`<form><div class="modal-head"><div><h2>${title}</h2><p>${esc(subtitle)}</p></div><button type="button" class="close" aria-label="Fechar">×</button></div><div class="form-body"><p class="error" role="alert"></p>${html}</div><div class="modal-actions">${actions}</div></form>`;modal.querySelector('.close').onclick=()=>modal.close();modal.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>modal.close());if(!modal.open)modal.showModal();return modal.querySelector('form')}
function error(e){modal.querySelector('.error').textContent=e.message}
let googleScript;
function loadGoogle(){if(window.google?.accounts?.id)return Promise.resolve();if(!googleScript)googleScript=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://accounts.google.com/gsi/client';script.async=true;script.onload=resolve;script.onerror=()=>{googleScript=null;script.remove();reject(new Error('Não foi possível carregar o Google. Recarregue a página.'));};document.head.append(script);});return googleScript;}
async function renderLogin(){
 teamMode='';pageMode=false;pageReferences=[];pageQuery='';
 if(modal.open)modal.close();
 app.innerHTML=`<div class="login-page"><section class="login-story"><div class="login-brand"><span class="brand-mark">T</span><strong>TASSITANI<span>CENTRAL DE CONTEÚDOS</span></strong></div><div class="login-editorial"><span class="login-kicker">REPERTÓRIO EM MOVIMENTO</span><h1>Boas ideias<br>merecem<br><em>sair do papel.</em></h1><p>Referências, olhares e próximos passos.<br>O nosso espaço para criar juntos.</p><div class="login-tags"><span>Referências</span><span>Ideias</span><span>Produção</span></div></div><footer>Um lugar para guardar. Um ponto de partida para criar.</footer></section><section class="login-access"><div class="login-box"><span class="login-eyebrow">SEU ESPAÇO DE CRIAÇÃO</span><h2>Que bom ter<br>você por aqui.</h2><p>Entre na sua conta para acessar a central<br>e continuar de onde parou.</p>${currentUser?`<button class="btn primary saved-login" id="continue-session">Continuar como ${esc(currentUser.name.split(' ')[0])}</button><button class="text-btn switch-account" id="switch-account">Usar outra conta</button>`:'<div id="google-login"></div>'}<p id="login-error" role="alert"></p>${authConfig.passwordEnabled?`<details class="owner-access"><summary>Acesso do proprietário com senha</summary><form id="owner-login"><label>E-mail<input name="email" type="email" required autocomplete="username" ></label><label>Senha<input name="password" type="password" required autocomplete="current-password"></label><button class="btn primary" type="submit">Entrar na central</button></form></details>`:''}<div class="login-private">Acesso exclusivo da equipe<br><span>Sua conexão fica salva por até 90 dias neste navegador.</span></div></div><footer>Central Tassitani · Conteúdo com intenção.</footer></section></div>`;
 const error=document.querySelector('#login-error');
 const enter=async result=>{currentUser=result.user;editor=true;await refresh();};
 if(currentUser){document.querySelector('#continue-session').onclick=async()=>{try{await enter(authConfig)}catch(e){currentUser=null;editor=false;await renderLogin()}};document.querySelector('#switch-account').onclick=async()=>{await api('logout','POST',{});currentUser=null;editor=false;items=[];await renderLogin()};return;}
 const form=document.querySelector('#owner-login');if(form)form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('button');button.disabled=true;error.textContent='';try{await enter(await api('login','POST',{email:form.email.value,password:form.password.value}));}catch(e){error.textContent=e.message;}finally{button.disabled=false;}};
 if(!authConfig.googleClientId){document.querySelector('#google-login').innerHTML='<p class="google-pending">A conexão com o Google está sendo preparada.</p>';return;}
 try{await loadGoogle();const {nonce}=await api('auth/challenge');if(!document.querySelector('#google-login'))return;window.google.accounts.id.initialize({client_id:authConfig.googleClientId,nonce,auto_select:false,callback:async response=>{error.textContent='Conectando…';try{await enter(await api('auth/google','POST',{credential:response.credential}));}catch(e){await renderLogin();document.querySelector('#login-error').textContent=e.message;}}});window.google.accounts.id.renderButton(document.querySelector('#google-login'),{type:'standard',theme:'outline',size:'large',text:'continue_with',shape:'pill',width:300,locale:'pt-BR'});}catch(e){error.textContent=e.message;}
}
function login(){renderLogin();}

function catSelect(selected){return Object.entries(categories).map(([k,c])=>`<option value="${k}" ${selected===k?'selected':''}>${c.name}</option>`).join('')}
function edit(i){const existing=!!i,readonly=existing&&!editor;i=i||{title:'',notes:'',url:'',category:category==='all'?'reels':category,status:'pending'};const f=show(existing?'Sua ideia, seu próximo conteúdo':'Novo conteúdo',readonly?'Explore a referência e as ideias salvas.':'Salve a referência e desenvolva o seu olhar.',`${existing&&i.url?`<details class="form-options"><summary>Ver referência</summary><div class="detail-preview">${preview(i,true)}</div><a class="btn" href="${esc(i.url)}" target="_blank" rel="noopener noreferrer">Abrir no Instagram ${icon('arrow')}</a><p class="source">A prévia depende da disponibilidade da publicação no Instagram.</p></details>`:''}${existing&&editor?'<label class="upload">Definir ou trocar capa<input name="cover" type="file" accept="image/png,image/jpeg,image/webp"></label>':''}<fieldset ${readonly?'disabled':''} style="border:0;padding:0;margin:0"><label class="field">Título ou tema<input name="title" maxlength="1000" value="${esc(i.title)}" placeholder="Opcional ao colar um link"></label><label class="field">Link do Instagram <span class="muted">(opcional)</span><input name="url" type="url" value="${esc(i.url)}" placeholder="https://www.instagram.com/reel/..."></label><label class="field">@ do criador<input name="creator_handle" maxlength="31" value="${esc(i.creator_handle||'')}" placeholder="@usuario" pattern="@?[A-Za-z0-9._]{1,30}"><small>Perfil da referência, diferente de quem adicionou à central.</small></label><div class="form-row"><label class="field">Categoria<select name="category">${catSelect(i.category)}</select></label><label class="field">Andamento<select name="status">${[['pending','Não feito'],['producing','Em produção'],['done','Feito / gravado']].map(([k,v])=>`<option value="${k}" ${i.status===k?'selected':''}>${v}</option>`).join('')}</select></label></div><details class="template-fields form-options" ${i.category==='carrosseis'?'':'hidden'}><summary>Editar template visual</summary><label class="field">Nome do template<input name="template_name" maxlength="200" value="${esc(i.template_name||'')}" placeholder="Ex.: CARR-001 · Editorial em preto e branco"></label><label class="field">Descrição visual<textarea name="visual_description" maxlength="12000" rows="5" placeholder="Cores, tipografia, composição, imagens e detalhes que quer preservar...">${esc(i.visual_description||'')}</textarea></label><label class="field">Base da descrição<input name="visual_basis" maxlength="300" value="${esc(i.visual_basis||'')}" placeholder="Ex.: Capa observada; slides internos ainda não conferidos"></label></details><label class="field">Minhas ideias<textarea name="notes" rows="6" maxlength="30000" placeholder="Seu gancho, roteiro, adaptação ou o que gostou neste formato...">${esc(i.notes)}</textarea></label></fieldset>${existing?templateSection(i)+transcriptButton(i):''}${i.source?`<p class="source">Importado de <a href="${esc(i.source_url)}" target="_blank" rel="noopener noreferrer">${esc(i.source)}</a></p>`:''}`,`${existing&&editor?'<button class="text-btn danger" type="button" id="delete">Excluir</button>':''}<button class="btn" type="button" data-close>Fechar</button>${readonly?'<button class="btn primary" type="button" id="login-edit">Editar conteúdo</button>':'<button class="btn primary" type="submit">Salvar conteúdo</button>'}`);
 bindMedia(f);bindTemplateCopy(f);bindTranscripts(f);
 f.querySelector('[name=category]').onchange=e=>{f.querySelector('.template-fields').hidden=e.target.value!=='carrosseis'};
 if(readonly){f.querySelector('#login-edit').onclick=()=>login(()=>edit(i));return}
 f.onsubmit=async e=>{e.preventDefault();const button=f.querySelector('[type=submit]');button.disabled=true;try{const values=Object.fromEntries(new FormData(f));const payload={creator_handle:values.creator_handle,title:values.title,notes:values.notes,url:values.url,category:values.category,status:values.status,template_name:values.template_name,visual_description:values.visual_description,visual_basis:values.visual_basis};if(existing)await api('items/'+i.id,'PUT',{...payload,version:i.version});else {const result=await api('items','POST',{items:[payload]});if(!result.created)throw new Error('Este link já está salvo nesta categoria.');}modal.close();await refresh();toast('Conteúdo salvo.')}catch(e){error(e)}finally{button.disabled=false}};
 const del=f.querySelector('#delete');if(del)del.onclick=()=>{const confirm=show('Excluir este conteúdo?','Esta ação remove a referência e suas ideias.',`<p>${esc(i.title)}</p>`,`<button class="btn" type="button" id="back">Voltar</button><button class="btn primary">Excluir conteúdo</button>`);confirm.querySelector('#back').onclick=()=>edit(i);confirm.onsubmit=async e=>{e.preventDefault();try{await api('items/'+i.id,'DELETE',{});modal.close();await refresh();toast('Conteúdo excluído.')}catch(e){error(e)}}};
 const cover=f.querySelector('[name=cover]');if(cover)cover.onchange=async()=>{const file=cover.files[0];if(!file)return;if(file.size>5e6){error(new Error('A capa deve ter até 5 MB.'));return}try{const image=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});const draft=Object.fromEntries(new FormData(f));await api('items/'+i.id+'/thumbnail','POST',{image});await refresh();edit({...items.find(x=>x.id===i.id),creator_handle:draft.creator_handle,title:draft.title,notes:draft.notes,url:draft.url,category:draft.category,status:draft.status,template_name:draft.template_name,visual_description:draft.visual_description,visual_basis:draft.visual_basis});toast('Capa atualizada.')}catch(e){error(e)}};
}
function batch(){const f=show('Importar referências','Novos links entram como Não feito, com data e responsável.',`<label class="field">Adicionar à categoria<select name="category">${catSelect(category==='all'?'reels':category)}</select></label><label class="field">Cole os links<textarea name="links" required rows="8" placeholder="https://www.instagram.com/reel/...\nhttps://www.instagram.com/p/..." autofocus></textarea><small>Até 500 links por lote. Links repetidos na mesma categoria são ignorados.</small></label><details class="form-options"><summary>Opções do lote</summary><label class="field">@ do criador <span class="muted">(se for o mesmo em todos)</span><input name="creator_handle" maxlength="31" pattern="@?[A-Za-z0-9._]{1,30}" placeholder="@usuario"></label><label class="field">Ideia para este lote <span class="muted">(opcional)</span><textarea name="notes" rows="2" placeholder="O que você quer aproveitar destas referências?"></textarea></label></details><p id="batch-count" class="source">Nenhum link identificado.</p>`,`<button class="btn" type="button" data-close>Cancelar</button><button class="btn primary" type="submit">Importar links</button>`);const extract=()=>f.links.value.match(/https?:\/\/[^\s<>"']+/g)||[];f.links.oninput=()=>f.querySelector('#batch-count').textContent=`${extract().length} links identificados para revisão.`;f.onsubmit=async e=>{e.preventDefault();const links=extract();if(!links.length){error(new Error('Cole pelo menos um link completo.'));return}const button=f.querySelector('[type=submit]');button.disabled=true;try{const data=links.map((url,n)=>({url,title:'Referência '+(url.match(/\/(?:p|reel|reels|tv)\/([\w-]+)/)?.[1]||n+1),category:f.category.value,status:'pending',creator_handle:f.creator_handle.value,notes:f.notes.value}));const result=await api('items','POST',{items:data});category=f.category.value;status='all';query='';sort='new';page=1;media=transcript=engagement='all';minLikes=minComments='';modal.close();await refresh();toast(`${result.created} referências importadas · ${result.duplicates} repetidas ignoradas.`)}catch(e){error(e)}finally{button.disabled=false}}}
async function exportItems(){try{const exported=await api('export');const blob=new Blob([JSON.stringify(exported,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='acervo-tassitani.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Acervo exportado com ideias, templates e transcrições.')}catch(e){toast(e.message)}}
try{authConfig=await api('session');currentUser=authConfig.user;editor=false;await renderLogin();}catch(e){app.innerHTML=`<div class="empty"><h1>Não foi possível abrir a central</h1><p>${esc(e.message)}</p><button class="btn" onclick="location.reload()">Tentar novamente</button></div>`;}
setInterval(async()=>{if(editor&&!pageMode&&!teamMode&&!modal.open&&!document.querySelector('.notes-form')&&!document.querySelector('.card-details[open]')){try{const next=await api('items');if(JSON.stringify(next)!==JSON.stringify(items)){items=next;render();}}catch(e){if(e.status===401){currentUser=null;editor=false;items=[];renderLogin();}}}},30000);
if(document.modelContext?.registerTool){try{await document.modelContext.registerTool({name:'list_content_references',description:'Lista as referências atualmente visíveis na central, respeitando os filtros.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async(input)=>{if(!input||Array.isArray(input)||typeof input!=='object'||Object.keys(input).length)throw new Error('Esta consulta aceita apenas um objeto vazio.');return filtered().map(({id,title,category,status,url,notes})=>({id,title,category,status,url,notes}))}})}catch{}}

async function renderPageReferences(){
 const workspace=document.querySelector('.workspace');workspace.innerHTML='<p role="status">Carregando suas páginas…</p>';
 try{const rows=await api('pages');if(!pageMode||!pageOwner()||!workspace.isConnected)return;pageReferences=rows;
 document.querySelector('.breadcrumb b').textContent='Página de Referência';document.querySelector('.public-badge').textContent='Somente você';
 workspace.innerHTML=`<div class="heading"><div><div class="eyebrow">SEU REPERTÓRIO PRIVADO</div><h1>Página de Referência</h1><p class="subtitle">Páginas que inspiram suas próximas criações.</p></div><button class="btn primary" id="new-page">${icon('plus')}Adicionar página</button></div><div class="controls"><label class="search">${icon('search')}<input id="page-search" placeholder="Buscar página ou anotação…" aria-label="Buscar páginas" value="${esc(pageQuery)}"></label><span class="source">${rows.length} páginas · acesso exclusivo</span></div><div class="page-reference-grid"></div>`;
 workspace.querySelector('#new-page').onclick=()=>editPageReference();workspace.querySelector('#page-search').oninput=e=>{pageQuery=e.target.value;paintPageReferences();};paintPageReferences();
 }catch(e){if(workspace.isConnected)workspace.innerHTML=`<p role="alert">${esc(e.message)}</p>`;}
}
function paintPageReferences(){
 const grid=document.querySelector('.page-reference-grid');if(!grid)return;
 const rows=pageReferences.filter(p=>(p.title+' '+p.url+' '+p.notes).toLocaleLowerCase('pt-BR').includes(pageQuery.toLocaleLowerCase('pt-BR')));
 grid.innerHTML=rows.length?rows.map(p=>`<article class="page-reference-card"><button class="page-screenshot" data-page-preview="${p.id}" aria-label="Ampliar print de ${esc(p.title)}"><img src="/api/pages/${p.id}/image?v=${p.version}" alt="Primeira dobra de ${esc(p.title)}" loading="lazy"><span>Ampliar print</span></button><div class="page-reference-body"><h2>${esc(p.title)}</h2><div class="reference-meta"><span>${esc(new URL(p.url).hostname)}</span><time title="Adicionado em" datetime="${esc(p.created_at)}">${new Date(p.created_at).toLocaleDateString('pt-BR')}</time></div><details class="card-details"><summary>Anotações</summary><p class="page-note">${esc(p.notes||'Nenhuma anotação ainda.')}</p><button class="text-btn" data-page-edit="${p.id}">Editar anotações</button></details><div class="page-reference-actions"><a class="btn" href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">Abrir página ${icon('arrow')}</a><button class="small-btn" data-page-edit="${p.id}" aria-label="Editar ${esc(p.title)}">${icon('edit')}Editar</button></div></div></article>`).join(''):'<p class="empty">Nenhuma página encontrada.</p>';
 grid.querySelectorAll('[data-page-edit]').forEach(b=>b.onclick=()=>editPageReference(pageReferences.find(p=>p.id===+b.dataset.pageEdit)));
 grid.querySelectorAll('[data-page-preview]').forEach(b=>b.onclick=()=>{const p=pageReferences.find(p=>p.id===+b.dataset.pagePreview);show(esc(p.title),'Print da primeira dobra · '+new Date(p.captured_at).toLocaleDateString('pt-BR'),`<img class="page-large-print" src="/api/pages/${p.id}/image?v=${p.version}" alt="${esc(p.title)}">`,`<button type="button" class="btn" data-close>Fechar</button><a class="btn primary" href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">Abrir página ↗</a>`);modal.classList.add('page-preview-modal');modal.addEventListener('close',()=>modal.classList.remove('page-preview-modal'),{once:true});});
}
function editPageReference(p){
 modal.classList.remove('page-preview-modal');
 const f=show(p?'Editar página':'Adicionar página','Visível somente para você.',`<label class="field">Nome<input name="title" maxlength="200" value="${esc(p?.title||'')}" placeholder="Nome da referência"></label><label class="field">Endereço<input name="url" type="url" required maxlength="2000" value="${esc(p?.url||'')}" placeholder="https://..."></label><label class="field">Print da primeira dobra<input name="image" type="file" accept="image/jpeg,image/png,image/webp" ${p?'':'required'}><small>${p?'Escolha uma imagem para substituir o print atual.':'Selecione uma captura da parte inicial da página.'} Até 5 MB.</small></label><label class="field">Anotações<textarea name="notes" rows="4" maxlength="10000" placeholder="O que você quer usar como inspiração?">${esc(p?.notes||'')}</textarea></label>`,`${p?'<button type="button" class="text-btn danger" id="remove-page">Excluir</button>':''}<button type="button" class="btn" data-close>Cancelar</button><button type="submit" class="btn primary">Salvar página</button>`);
 f.onsubmit=async e=>{e.preventDefault();const button=f.querySelector('[type=submit]');button.disabled=true;try{const data={title:f.elements.title.value,url:f.elements.url.value,notes:f.elements.notes.value,version:p?.version};const file=f.elements.image.files[0];if(file){if(file.size>5e6)throw Error('O print deve ter até 5 MB.');data.image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Não foi possível ler o print.'));reader.readAsDataURL(file);});}await api('pages'+(p?'/'+p.id:''),p?'PUT':'POST',data);modal.close();await renderPageReferences();toast('Página salva.');}catch(e){error(e);}finally{button.disabled=false;}};
 if(p)f.querySelector('#remove-page').onclick=()=>{const confirm=show('Excluir esta página?',p.title,'<p>O print e as anotações serão removidos.</p>','<button class="btn" type="button" data-close>Cancelar</button><button class="btn primary" type="submit">Excluir página</button>');confirm.onsubmit=async e=>{e.preventDefault();try{await api('pages/'+p.id,'DELETE',{});modal.close();await renderPageReferences();toast('Página excluída.');}catch(e){error(e);}};};
}


async function renderTeam(){const workspace=document.querySelector('.workspace'),mode=teamMode;if(!mode)return;workspace.innerHTML='<p class="result-info">Carregando…</p>';try{const [config,rows]=await Promise.all([api('team'),api(mode)]);if(teamMode!==mode||!workspace.isConnected)return;teamConfig=config;teamRows=rows;drawTeam();}catch(e){workspace.textContent=e.message;}}
function drawTeam(){const tasks=teamMode==='tasks',w=document.querySelector('.workspace'),names=Object.fromEntries(teamConfig.members.map(m=>[m.email,m.name])),labels={pending:'A fazer',producing:'Em andamento',done:'Concluída'},today=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
 w.innerHTML=`<div class="heading"><div><h1>${tasks?'Tarefas':'Central de Pastas'}</h1><p class="subtitle">${tasks?'Sua equipe, os próximos passos.':'Os arquivos da equipe, em um só lugar.'}</p></div><button id="team-add" class="btn primary">${icon('plus')}${tasks?'Nova tarefa':'Adicionar pasta'}</button></div>${tasks?`<div class="controls"><select id="task-person" aria-label="Responsável"><option value="">Toda a equipe</option>${teamConfig.members.map(m=>`<option value="${esc(m.email)}" ${taskAssignee===m.email?'selected':''}>${esc(m.name)}</option>`).join('')}</select><select id="task-status" aria-label="Status"><option value="">Todos os status</option>${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${taskStatus===k?'selected':''}>${v}</option>`).join('')}<option value="late" ${taskStatus==='late'?'selected':''}>Atrasadas</option></select></div>${!teamConfig.email_configured?'<p class="team-notice">Avisos por e-mail aguardam a conexão do remetente.</p>':''}<div class="task-list">${teamRows.filter(t=>(!taskAssignee||t.assignee===taskAssignee)&&(!taskStatus||(taskStatus==='late'?t.due_date<today&&t.status!=='done':t.status===taskStatus))).map(t=>`<article class="task-row"><span class="task-dot ${t.status}"></span><div class="task-info"><h3>${esc(t.title)}</h3><div class="task-meta"><span>${esc(names[t.assignee])}</span><span class="${t.due_date<today&&t.status!=='done'?'late':''}">${esc(t.due_date.split('-').reverse().join('/'))}${t.due_date<today&&t.status!=='done'?' · Atrasada':''}</span><span>${labels[t.status]}</span></div>${t.description?`<details><summary>Detalhes</summary><p class="task-description">${esc(t.description)}</p></details>`:''}</div><button class="btn" data-team-edit="${t.id}" aria-label="Editar ${esc(t.title)}">${icon('edit')}Editar</button></article>`).join('')||'<div class="team-empty">Nenhuma tarefa por aqui.</div>'}</div>`:teamConfig.categories.map(category=>`<section class="folder-section"><h2>${esc(category)}</h2><div class="folder-grid">${teamRows.filter(f=>f.category===category).map(f=>`<article class="folder-card"><a href="${esc(f.url)}" target="_blank" rel="noopener noreferrer">${icon('link')}<strong>${esc(f.title)}</strong>${icon('arrow')}</a><small>${esc(new URL(f.url).hostname)}</small><button class="text-btn" data-team-edit="${f.id}">${icon('edit')}Editar</button></article>`).join('')||'<div class="team-empty">Adicione o primeiro link desta categoria.</div>'}</div></section>`).join('')}`;
 document.querySelector('#team-add').onclick=()=>editTeam();w.querySelectorAll('[data-team-edit]').forEach(b=>b.onclick=()=>editTeam(teamRows.find(r=>r.id===Number(b.dataset.teamEdit))));if(tasks){document.querySelector('#task-person').onchange=e=>{taskAssignee=e.target.value;drawTeam()};document.querySelector('#task-status').onchange=e=>{taskStatus=e.target.value;drawTeam()};}}
function editTeam(row){const tasks=teamMode==='tasks',mode=teamMode,labels={pending:'A fazer',producing:'Em andamento',done:'Concluída'},f=show(row?'Editar '+(tasks?'tarefa':'pasta'):(tasks?'Nova tarefa':'Adicionar pasta'),'',`<label>Nome<input name="title" required maxlength="180" value="${esc(row?.title)}"></label>${tasks?`<div class="form-grid"><label>Responsável<select name="assignee">${teamConfig.members.map(m=>`<option value="${esc(m.email)}" ${(row?.assignee||currentUser.email)===m.email?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label><label>Prazo<input type="date" name="due_date" required value="${esc(row?.due_date)}"></label></div><label>Status<select name="status">${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${row?.status===k?'selected':''}>${v}</option>`).join('')}</select></label><label>Detalhes<textarea name="description" maxlength="10000" rows="4" placeholder="O que precisa ser feito?">${esc(row?.description)}</textarea></label><p class="result-info">${teamConfig.email_configured?'Aviso ao responsável e lembretes na véspera e no dia do prazo.':'A tarefa será salva. Os avisos aguardam a conexão do e-mail.'}</p>`:`<label>Categoria<select name="category">${teamConfig.categories.map(c=>`<option ${row?.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label>Link da pasta<input type="url" name="url" required placeholder="https://drive.google.com/…" value="${esc(row?.url)}"></label>`}`,`${row?'<button type="button" id="team-delete" class="text-btn">Excluir</button>':''}<button type="button" class="btn" data-close>Cancelar</button><button type="submit" class="btn primary">Salvar</button>`);
 f.classList.add('team-form');f.onsubmit=async e=>{e.preventDefault();const button=f.querySelector('[type=submit]');button.disabled=true;try{const data=Object.fromEntries(new FormData(f));if(row)data.version=row.version;await api(mode+(row?'/'+row.id:''),row?'PUT':'POST',data);modal.close();await renderTeam();toast('Salvo.');}catch(e){error(e)}finally{button.disabled=false}};
 if(row)f.querySelector('#team-delete').onclick=()=>{const confirm=show('Excluir '+(tasks?'tarefa?':'pasta?'),row.title,'<p>Esta ação remove o registro da central.</p>','<button type="button" class="btn" data-close>Cancelar</button><button type="submit" class="btn primary">Excluir</button>');confirm.onsubmit=async e=>{e.preventDefault();try{await api(mode+'/'+row.id,'DELETE',{version:row.version});modal.close();await renderTeam();toast('Excluído.')}catch(e){error(e)}};};}
